def check_triples(p_max, a_max, b_max):
    results = []
    for p in range(3, p_max + 1):
        if not is_prime(p):
            continue
        for a in range(1, a_max + 1):
            for b in range(a, b_max + 1):
                val1 = a**(p-1) + b
                val2 = b**(p-1) + a
                if is_power_of_p(val1, p) and is_power_of_p(val2, p):
                    results.append((p, a, b))
    return results

def is_prime(n):
    if n < 2: return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def is_power_of_p(n, p):
    if n <= 0: return False
    while n > 1:
        if n % p != 0:
            return False
        n //= p
    return n == 1

